    private fun changeMonth(delta: Int) {
        var next: compat.time.YearMonth? = month!!.plusMonths(delta.toLong())
        if (((next!!.year) >= 1900 && (next!!.year) <= 2100)) {
            month = next
            render()
        }
    }
    private fun pickMonth() {
        var f: android.widget.LinearLayout? = form()
        hint(f, "בחר חודש ושנה להצגה. טווח התאריכים המדויק מופיע למטה.")
        var year: android.widget.EditText? = field(f, "שנה", String.valueOf(month!!.year), true)
        run { year!!.inputType = android.text.InputType.TYPE_CLASS_NUMBER }
        run { year!!.tag = "period-year" }
        var selected: IntArray? = intArrayOf(month!!.monthValue)
        var chips: MutableList<android.widget.TextView>? = ArrayList<android.widget.TextView>()
        var preview: android.widget.TextView? = bold("", 16, INK)
        run { preview!!.gravity = android.view.Gravity.CENTER }
        run { preview!!.textDirection = android.view.View.TEXT_DIRECTION_LTR }
        var active: Array<android.app.AlertDialog>? = (arrayOf<android.app.AlertDialog?>(null) as Array<android.app.AlertDialog>)
        var update: compat.j.Runnable? = compat.j.Runnable l33@{
            var y: Int = 0
            try {
                y = Int.parseInt(((year!!.getText())!!.toString())!!)
            } catch (ignored: NumberFormatException) {
            }
            var valid: Boolean = y >= 1900 && y <= 2100
            preview!!.setText((if (valid) periodRange(compat.time.YearMonth.of(y, selected!![0])) else "יש להזין שנה בין 1900 ל־2100"))
            preview!!.setTextColor((if (valid) INK else RED))
            if ((active!![0] != null)) {
                run { ((active!![0])!!.getButton(android.app.AlertDialog.BUTTON_POSITIVE))!!.isEnabled = valid }
            }
            run {
                var i: Int = 0
                while (i < (chips!!.size)) {
                    var checked: Boolean = (i + 1) == (selected!![0])
                    run { (chips!!.get(i))!!.background = outlineShape((if (checked) CONTAINER else SURFACE), 12, (if (checked) PRIMARY else OUTLINE)) }
                    (chips!!.get(i))!!.setTextColor((if (checked) palette!!.onContainer else INK))
                    run { (chips!!.get(i))!!.isSelected = checked }
                    i++
                }
            }
        }
        run {
            var r: Int = 0
            while (r < 4) {
                var row: android.widget.LinearLayout? = row()
                run {
                    var c: Int = 0
                    while (c < 3) {
                        var m: Int = ((r * 3) + c) + 1
                        var chip: android.widget.TextView? = button(monthNames!![m - 1], false, compat.j.Runnable l34@{
                            selected!![0] = m
                            update!!.run()
                        })
                        run { chip!!.tag = "period-month-" + m }
                        chip!!.setTextSize(13f)
                        var lp: android.widget.LinearLayout.LayoutParams? = android.widget.LinearLayout.LayoutParams(0, -2, 1f)
                        lp!!.setMargins(dp(3f), dp(3f), dp(3f), dp(3f))
                        row!!.addView(chip, lp)
                        chips!!.add(chip!!)
                        c++
                    }
                }
                f!!.addView(row)
                r++
            }
        }
        space(f, 10)
        f!!.addView(preview)
        f!!.addView(textAction("התקופה הנוכחית", compat.j.Runnable l35@{
            month = (store!!.reporting())!!.label(compat.time.LocalDate.now())
            render()
            if ((active!![0] != null)) {
                (active!![0])!!.dismiss()
            }
        }))
        year!!.addTextChangedListener(changed(update))
        active!![0] = (dialog("בחירת חודש ושנה", f, MainActivity.Save l36@{
            var y: Int = Int.parseInt(((year!!.getText())!!.toString())!!)
            if ((y < 1900 || y > 2100)) {
                throw (IllegalArgumentException("יש להזין שנה בין 1900 ל־2100"))
            }
            month = compat.time.YearMonth.of(y, selected!![0])
            render()
        }))!!
        ((active!![0])!!.getButton(android.app.AlertDialog.BUTTON_POSITIVE))!!.setText("הצגת התקופה")
        update!!.run()
    }
