    private fun movements() {
        title(body, "התנועות שלך")
        var switches: android.widget.LinearLayout? = row()
        switches!!.addView(button("עסקאות", !chargesMode, compat.j.Runnable l42@{
            chargesMode = false
            render()
        }), android.widget.LinearLayout.LayoutParams(0, -2, 1f))
        switches!!.addView(button("לוח חיובים", chargesMode, compat.j.Runnable l43@{
            chargesMode = true
            render()
        }), android.widget.LinearLayout.LayoutParams(0, -2, 1f))
        body!!.addView(switches)
        space(body, 12)
        if ((chargesMode)) {
            var explanation: android.widget.LinearLayout? = card(body)
            hint(explanation, "לפי מועד ירידת הכסף. פירעון הכרטיס אינו הוצאה נוספת. חיוב קבוע הוא אומדן ללא חיבור לבנק, ריבית או עמלות שלא הוזנו.")
            var charges: MutableList<Store.Charge>? = store!!.periodCharges(month)
            var chargeTotal: Long = 0L
            for (charge in charges!!) {
