    private fun refreshList() {
        if ((listHost == null)) {
            return
        }
        var period: ReportPeriod? = store!!.reporting()
        listHost!!.removeAllViews()
        var found: MutableList<Store.Tx>? = ArrayList<Store.Tx>()
        var expense: Long = 0L
        var income: Long = 0L
        var pendingExpense: Long = 0L
        var pendingIncome: Long = 0L
        for (t in (store!!.transactions())!!) {
            if ((!(advancedFilter!!.matches(t, month, period, categoryFilter, accountFilter, merchantFilter, query)))) {
                continue
            }
            found!!.add(t!!)
            if (((t!!.status) == 1)) {
                if (((t!!.kind)!!.equals("income"))) {
                    income = compat.util.Math.addExact(income, t!!.amount)
                } else {
                    expense = compat.util.Math.addExact(expense, Store.netExpense(t))
                }
            } else {
                if (((t!!.kind)!!.equals("income"))) {
                    pendingIncome = compat.util.Math.addExact(pendingIncome, t!!.amount)
                } else {
                    pendingExpense = compat.util.Math.addExact(pendingExpense, Store.netExpense(t))
                }
            }
        }
        var summary: android.widget.LinearLayout? = card(listHost)
        run { summary!!.background = shape(CONTAINER, 24) }
        hint(summary, "סה״כ הוצאות שבוצעו")
        var total: android.widget.TextView? = bold(money(expense), 32, palette!!.onContainer)
        run { total!!.tag = "movements-total" }
        summary!!.addView(total)
        if ((!((workHours(expense))!!.isEmpty()))) {
            hint(summary, workHours(expense))
        }
        hint(summary, (found!!.size).toString() + " תנועות · לפי טווח התאריכים והסינון הנבחרים")
        var expected: android.widget.TextView? = text("הוצאות צפויות: " + money(pendingExpense), 15, palette!!.onContainer)
        run { expected!!.tag = "movements-pending" }
        summary!!.addView(expected)
        if ((incomes() || income > 0 || pendingIncome > 0)) {
            var received: android.widget.TextView? = text("הכנסות שבוצעו: " + money(income), 15, palette!!.onContainer)
            run { received!!.tag = "movements-income" }
            summary!!.addView(received)
            var net: android.widget.TextView? = text("הוצאות פחות הכנסות שבוצעו: " + money(expense - income), 15, palette!!.onContainer)
            run { net!!.tag = "movements-net" }
            summary!!.addView(net)
            if ((pendingIncome > 0)) {
                summary!!.addView(text("הכנסות צפויות: " + money(pendingIncome), 15, palette!!.onContainer))
            }
        }
        if ((found!!.isEmpty())) {
            var empty: android.widget.LinearLayout? = card(listHost)
            hint(empty, "אין תנועות שמתאימות לבחירה.")
        }
        run {
            var n: Int = 0
            while (n < (compat.util.Math.min(found!!.size, movementLimit))) {
                txRow(card(listHost), found!!.get(n))
                n++
            }
        }
        if (((found!!.size) > movementLimit)) {
            listHost!!.addView(button("הצגת תנועות נוספות (" + compat.util.Math.min(movementLimit, found!!.size) + " מתוך " + found!!.size + ")", false, compat.j.Runnable l50@{
                movementLimit = movementLimit + 60
                refreshList()
            }))
        }
        if ((tab == 1)) {
            lastScreen = captureScreen()
        }
    }
