    private fun chartsPage(scroll: android.widget.ScrollView?) {
        title(body, "כל הגרפים")
        var reorder: android.widget.TextView? = button("שינוי סדר הגרפים", false, compat.j.Runnable { this.chartOrderDialog() })
        run { reorder!!.tag = "graph-reorder" }
        body!!.addView(reorder)
        space(body, 12)
        var overview: Store.Overview? = store!!.overview(month)
        var order: MutableList<Int>? = ChartCatalog.order((Tools.read(this))!!.optString("chartOrder"))
        var pending: MutableMap<android.widget.LinearLayout, Int>? = LinkedHashMap<android.widget.LinearLayout, Int>()
        for (id in order!!) {
            var section: android.widget.LinearLayout? = card(body)
            run { section!!.tag = "graph-section-" + id }
            title(section, ChartCatalog.LABELS!!.get(id))
            var content: android.widget.LinearLayout? = column()
            run { content!!.minimumHeight = dp(280f) }
            section!!.addView(content)
            pending!!.put(content!!, id)
        }
        var drawVisible: compat.j.Runnable? = compat.j.Runnable l53@{
            if ((!(scroll!!.isAttachedToWindow) || (scroll!!.height) == 0)) {
                return@l53
            }
            var cutoff: Int = ((scroll!!.scrollY) + (scroll!!.height)) + (dp(180f))
            var entries: MutableIterator<MutableMap.MutableEntry<android.widget.LinearLayout, Int>>? = (pending!!.entries)!!.iterator()
            while ((entries!!.hasNext())) {
                var entry: MutableMap.MutableEntry<android.widget.LinearLayout, Int>? = entries!!.next()
                var content: android.widget.LinearLayout? = entry!!.key
                var section: android.view.View? = ((content!!.parent) as android.view.View?)
                if (((section!!.top) > cutoff)) {
                    break
                }
                if (((section!!.bottom) >= ((scroll!!.scrollY) - (dp(180f))))) {
                    entries!!.remove()
                    run { content!!.minimumHeight = 0 }
                    drawHomeChart(content, (entry!!.value)!!, overview)
                    break
                }
            }
        }
        body!!.addOnLayoutChangeListener(android.view.View.OnLayoutChangeListener l54@{ v, l, t, r, b, oldL, oldT, oldR, oldB -> scroll!!.post(drawVisible) })
        scroll!!.setOnScrollChangeListener(android.view.View.OnScrollChangeListener l55@{ v, x, y, oldX, oldY -> drawVisible!!.run() })
        scroll!!.post(drawVisible)
    }
    private fun chartOrderDialog() {
