    private fun drawChartOrder(rows: android.widget.LinearLayout?, order: MutableList<Int>?) {
        rows!!.removeAllViews()
        run {
            var index: Int = 0
            while (index < (order!!.size)) {
                var position: Int = index
                var name: String? = ChartCatalog.LABELS!!.get((order!!.get(index))!!)
                var row: android.widget.LinearLayout? = row()
                row!!.addView(text((index + 1).toString() + ". " + name, 15, INK), android.widget.LinearLayout.LayoutParams(0, -2, 1f))
                var up: android.widget.TextView? = button("↑", false, compat.j.Runnable l58@{
                    ChartCatalog.move(order, position, -1)
                    drawChartOrder(rows, order)
                })
                run { up!!.tag = "graph-up-" + order!!.get(index) }
                run { up!!.contentDescription = "העלאת " + name }
                run { up!!.isEnabled = index > 0 }
                var down: android.widget.TextView? = button("↓", false, compat.j.Runnable l59@{
                    ChartCatalog.move(order, position, 1)
                    drawChartOrder(rows, order)
                })
                run { down!!.tag = "graph-down-" + order!!.get(index) }
                run { down!!.contentDescription = "הורדת " + name }
                run { down!!.isEnabled = index < ((order!!.size) - 1) }
                row!!.addView(up)
                row!!.addView(down)
                rows!!.addView(row)
                index++
            }
        }
    }
    private fun drawHomeChart(host: android.widget.LinearLayout?, choice: Int, overview: Store.Overview?) {
        host!!.removeAllViews()
        space(host, 8)
        if ((choice >= 5)) {
            advancedChart(host, choice, overview)
            return
        }
        if ((choice == 4)) {
            host!!.addView(bold(monthNames!![(month!!.monthValue) - 1] + " " + month!!.year, 18, INK))
            var values: MutableMap<String, Long>? = LinkedHashMap<String, Long>()
            values!!.put("הוראות קבע", overview!!.recurring)
            values!!.put("חיובים מזדמנים", overview!!.occasional)
            var chart: ChartView? = ChartView(this, values, true, null)
            run { chart!!.tag = "home-chart" }
            host!!.addView(chart, android.widget.LinearLayout.LayoutParams(-1, dp(260f)))
            legend(host, values, null)
            hint(host, "התקופה הנבחרת · כולל חיובים שבוצעו וצפויים. מעבר בין חודשים מציג כל חודש בנפרד.")
            return
        }
        if ((choice == 3)) {
            var values: MutableMap<String, Long>? = LinkedHashMap<String, Long>()
            var months: MutableMap<String, compat.time.YearMonth>? = HashMap<String, compat.time.YearMonth>()
            run {
                var i: Int = 5
                while (i >= 0) {
                    var m: compat.time.YearMonth? = month!!.minusMonths(i.toLong())
                    var label: String? = (m!!.monthValue).toString() + "/" + ((m!!.year) % 100)
                    values!!.put(label!!, (store!!.overview(m))!!.total())
                    months!!.put(label!!, m!!)
                    i--
                }
            }
            var chart: ChartView? = ChartView(this, values, false, ChartView.Pick l60@{ key ->
                month = months!!.get(key!!)
                tab = 1
                categoryFilter = ""
                merchantFilter = ""
                accountFilter = 0L
                query = ""
                advancedFilter = MovementFilter()
                chargesMode = false
                render()
            })
            run { chart!!.tag = "home-chart" }
            host!!.addView(chart, android.widget.LinearLayout.LayoutParams(-1, dp(240f)))
            hint(host, "חיובים שבוצעו וצפויים, כולל הוראות קבע. לחיצה על עמודה פותחת את החודש.")
            return
        }
        var values: MutableMap<String, Long>? = (if (choice == 1) overview!!.merchants else (if (choice == 2) overview!!.payments else overview!!.categories))
        var pick: ChartView.Pick? = (if (choice == 1) ChartView.Pick { a0 -> this.showMerchant(a0) } else (if (choice == 2) ChartView.Pick { a0 -> this.showPayment(a0) } else ChartView.Pick { a0 -> this.showCategory(a0) }))
        hint(host, "כולל הוראות קבע וחיובים צפויים · זיכויים מקוזזים בסכומים. בטבעת מוצגות רק קבוצות עם הוצאה נטו חיובית.")
        var chart: ChartView? = ChartView(this, values, true, pick)
        run { chart!!.tag = "home-chart" }
        host!!.addView(chart, android.widget.LinearLayout.LayoutParams(-1, dp(260f)))
        legend(host, values, pick)
        if ((values!!.isEmpty())) {
            hint(host, "כשתוסיף חיובים, הפילוח שלך יופיע כאן.")
        }
    }
