    private fun advancedChart(host: android.widget.LinearLayout?, choice: Int, overview: Store.Overview?) {
        if ((choice == 5)) {
            var data: Store.SeriesData? = store!!.cumulative(month, compat.time.LocalDate.now())
            hint(host, "הוצאות נטו לאחר זיכויים · השוואה לאותם ימים בחודש הקודם · סכומים בשקלים")
            var chart: SeriesChartView? = SeriesChartView(this, data, true, null)
            run { chart!!.tag = "home-chart" }
            host!!.addView(chart, android.widget.LinearLayout.LayoutParams(-1, dp(260f)))
            var i: Int = 0
            for (entry in ((data!!.series)!!.entries)!!) {
                var amounts: LongArray? = entry!!.value
                host!!.addView(bold("● " + entry!!.key + ": " + money((if ((amounts!!.size) == 0) 0L else amounts!![(amounts!!.size) - 1])), 15, (ChartView.colors(this))!![i++]))
            }
            if (((data!!.labels)!!.isEmpty())) {
                hint(host, "בחודש עתידי עדיין אין קצב הוצאות שבוצעו.")
            } else {
                var selected: LongArray? = (data!!.series)!!.get("החודש הנבחר")
                var previous: LongArray? = (data!!.series)!!.get("החודש הקודם")
                var difference: Long = (selected!![(selected!!.size) - 1]) - (previous!![(previous!!.size) - 1])
                hint(host, "עד יום " + (data!!.labels)!!.size + " בתקופה: " + ((if (difference == 0L) "ללא שינוי לעומת החודש הקודם" else money(compat.util.Math.abs(difference)) + ((if (difference > 0) " יותר" else " פחות")) + " לעומת אותם ימים בחודש הקודם")))
            }
            return
        }
        if ((choice == 6)) {
            var options: MutableList<String>? = categoryOptions()
            var category: android.widget.Spinner? = spinner(host, "קטגוריה להצגה", options)
            run { category!!.tag = "trend-category" }
            var saved: String? = prefs!!.getString("trendCategory", "")
            category!!.setSelection(compat.util.Math.max(0, options!!.indexOf(saved!!)))
            var content: android.widget.LinearLayout? = column()
            host!!.addView(content)
            var update: compat.j.Runnable? = compat.j.Runnable l61@{
                var selected: String? = (category!!.selectedItem)!!.toString()
                ((prefs!!.edit())!!.putString("trendCategory", selected))!!.apply()
                content!!.removeAllViews()
                var values: MutableMap<String, Long>? = LinkedHashMap<String, Long>()
                var periods: MutableMap<String, compat.time.YearMonth>? = HashMap<String, compat.time.YearMonth>()
                run {
