    private fun recurring() {
        title(body, "הוראות קבע")
        var intro: android.widget.LinearLayout? = card(body)
        hint(intro, "החיובים נוצרים אוטומטית כצפויים לכל חודש שנפתח. פותחים את התנועה כדי לאשר שהחיוב בוצע או לעדכן את הסכום בפועל. חיובים באשראי משויכים לכרטיס שבחרת.")
        var rules: MutableList<Store.Rule>? = store!!.rules()
        var total: Long = 0L
