        for (r in rules!!) {
            if (((r!!.active) == 1)) {
                var due: MutableList<compat.time.LocalDate>? = (store!!.reporting())!!.ruleDates(r, month)
                if ((!(due!!.isEmpty()))) {
                    total = compat.util.Math.addExact(total, compat.util.Math.multiplyExact(store!!.expectedRuleAmount(r), due!!.size))
                    activeCount++
                }
            }
        }
        var summary: android.widget.LinearLayout? = card(body)
