        hint(summary, "סה״כ הוראות קבע לתקופה הנבחרת")
        var sum: android.widget.TextView? = bold(money(total), 32, palette!!.onContainer)
        run { sum!!.tag = "recurring-total" }
        summary!!.addView(sum)
        var count: android.widget.TextView? = text(activeCount.toString() + " הוראות קבע פעילות בתקופה זו", 14, palette!!.onContainer)
        run { count!!.tag = "recurring-count" }
        summary!!.addView(count)
        hint(summary, "לפי הסכומים שהוגדרו · ללא הוראות מושהות, שטרם התחילו או שהסתיימו")
        if ((rules!!.isEmpty())) {
            hint(intro, "אפשר להוסיף שכירות, תקשורת, מנויים וכל חיוב חודשי קבוע.")
        }
        for (r in rules!!) {
            var block: android.widget.LinearLayout? = card(body)
            block!!.addView(bold(r!!.name, 18, INK))
            block!!.addView(bold(money(store!!.expectedRuleAmount(r)) + ((if ((r!!.interval) == 12) " לשנה" else (if ((r!!.interval) == 3) " לרבעון" else " לחודש"))), 23, PRIMARY))
            hint(block, r!!.category + " · " + (store!!.account(r!!.account))!!.name)
            if ((!("ILS".equals(r!!.currency)))) {
                hint(block, Finance.decimal(r!!.originalAmount) + " " + r!!.currency + " · שער שמור " + r!!.fxRate + " · עמלת הכרטיס " + (store!!.account(r!!.account))!!.fxFee + "%")
            }
            hint(block, "החל מ־" + (compat.time.LocalDate.parse((r!!.start)!!))!!.format(displayDate!!) + ((if (((r!!.end)!!.javaTrim())!!.isEmpty()) "" else " עד " + (compat.time.LocalDate.parse((r!!.end)!!))!!.format(displayDate!!))))
            hint(block, (if ((r!!.active) == 1) "פעילה" else "מושהית"))
            hint(block, "עלות שנתית בקצב הנוכחי: " + money(((store!!.expectedRuleAmount(r)) * 12) / (r!!.interval)))
            var next: compat.time.LocalDate? = Analytics.next(r, compat.time.LocalDate.now())
            if (((r!!.active) == 1 && next != null)) {
                hint(block, "החיוב הבא: " + next!!.format(displayDate!!))
            }
            var paid: MutableList<Store.Tx>? = ArrayList<Store.Tx>()
            for (t in (store!!.transactions())!!) {
                if (((t!!.rule) == (r!!.id) && (t!!.status) == 1)) {
                    paid!!.add(t!!)
                }
            }
            if (((paid!!.size) > 1 && ((paid!!.get(0))!!.amount) != ((paid!!.get(1))!!.amount))) {
                hint(block, "שינוי בין שני חיובים שאושרו: " + money((paid!!.get(1))!!.amount) + " ← " + money((paid!!.get(0))!!.amount))
            }
            var edit: android.widget.TextView? = button("עריכת הוראת הקבע", false, compat.j.Runnable l69@{ ruleDialog(r) })
            run { edit!!.tag = "edit-rule-" + r!!.id }
            block!!.addView(edit)
            block!!.addView(button((if ((r!!.active) == 1) "השהיית הוראת הקבע" else "חידוש מהחודש הנבחר"), false, compat.j.Runnable l70@{
                if (((r!!.active) == 1)) {
                    (trackDialog((((((android.app.AlertDialog.Builder(this)).setTitle("השהיית " + r!!.name))!!.setMessage("תנועות צפויות מהיום והלאה יוסרו. חיובים שבוצעו יישמרו."))!!.setNegativeButton("ביטול", null))!!.setPositiveButton("השהיה", android.content.DialogInterface.OnClickListener l71@{ d, w ->
                        try {
                            edit("השהיית הוראת קבע", Store.Change l72@{ store!!.setRuleActive(r, false) })
                            render()
                        } catch (e: Exception) {
                            toast(e!!.message)
                        }
                    }))!!.create()))!!.show()
                } else {
                    var resume: compat.time.LocalDate? = Finance.day(compat.time.YearMonth.from(((store!!.reporting())!!.start(month))!!), (compat.time.LocalDate.parse((r!!.start)!!))!!.dayOfMonth)
                    if ((resume!!.isBefore(((store!!.reporting())!!.start(month))!!))) {
                        resume = Finance.day((compat.time.YearMonth.from(resume!!))!!.plusMonths(1L), (compat.time.LocalDate.parse((r!!.start)!!))!!.dayOfMonth)
                    }
                    r!!.start = resume!!.toString()
                    if ((!(((r!!.end)!!.javaTrim())!!.isEmpty()) && (compat.time.LocalDate.parse((r!!.end)!!))!!.isBefore((compat.time.LocalDate.parse((r!!.start)!!))!!))) {
                        toast("מועד הסיום עבר. יש ליצור הוראה חדשה.")
                        return@l70
                    }
                    edit("הפעלת הוראת קבע", Store.Change l73@{ store!!.setRuleActive(r, true) })
                    render()
                }
            }))
        }
    }
    private fun accountType(a: Store.Account?): String? {
        if (((a!!.type)!!.equals("cash"))) {
            return "מזומן"
        }
        if (((a!!.type)!!.equals("transfer"))) {
            return "העברה בנקאית"
        }
        run {
            var i: Int = 0
            while (i < (typeIds!!.size)) {
                if (((typeIds!![i])!!.equals(a!!.type))) {
                    return typeNames!![i]
                }
                i++
            }
        }
        return a!!.type
    }
