    private fun creditCycleDialog(a: Store.Account?) {
        store!!.ensureMonth(compat.time.YearMonth.from((Finance.creditCycleEnd(month, a!!.closing))!!))
        var f: android.widget.LinearLayout? = form()
        hint(f, "מ־" + (Finance.creditCycleStart(month, a!!.closing))!!.format(displayDate!!) + " עד " + (Finance.creditCycleEnd(month, a!!.closing))!!.format(displayDate!!))
        hint(f, "ירידת הכסף: " + (store!!.creditCyclePaymentDate(a, month))!!.format(displayDate!!))
        if (((a!!.type)!!.equals("fixed"))) {
            hint(f, "החיוב החודשי הקבוע שהוגדר: " + money(a!!.payment) + ". הפירעון מוגבל לחוב שהגיע למועד חיובו; יתרת התשלומים נשארת במסגרת.")
        }
        var txs: MutableList<Store.Tx>? = store!!.creditCycleTransactions(a, month)
        var actual: Long = 0L
        for (t in txs!!) {
            if ((Store.isSpending(t) && (t!!.status) == 1)) {
                actual = compat.util.Math.addExact(actual, Store.netExpense(t))
            }
        }
        var total: android.widget.TextView? = bold("סך רכישות שבוצעו במחזור: " + money(actual), 19, PRIMARY)
        run { total!!.tag = "credit-cycle-total" }
        f!!.addView(total)
        hint(f, "הרשימה לפי תאריך הרכישה. בעסקת תשלומים מוצג סכום הרכישה המלא; זה אינו סכום ירידת הכסף או יתרת החוב.")
        if ((txs!!.isEmpty())) {
            hint(f, "אין עסקאות במחזור זה")
