    private fun savedSearchDialog() {
        var searchMenu: Array<android.app.AlertDialog>? = (arrayOf<android.app.AlertDialog?>(null) as Array<android.app.AlertDialog>)
        var f: android.widget.LinearLayout? = form()
        var data: org.json.JSONObject? = Tools.read(this)
        var all: org.json.JSONArray? = data!!.optJSONArray("searches")
        if ((all == null || (all!!.length()) == 0)) {
            hint(f, "אין חיפושים שמורים. בחר סינונים ולחץ על שמירת החיפוש הנוכחי.")
        } else {
            run {
                var n: Int = 0
                while (n < (all!!.length())) {
                    try {
                        var index: Int = n
                        var item: org.json.JSONObject? = all!!.optJSONObject(n)
                        if ((item == null)) {
                            continue
                        }
                        f!!.addView(button(item!!.optString("name"), false, compat.j.Runnable l125@{
                            try {
                                advancedFilter = MovementFilter.from(item)
                                query = item!!.optString("query", "")
                                categoryFilter = item!!.optString("category", "")
                                merchantFilter = item!!.optString("merchant", "")
                                accountFilter = item!!.optLong("account", 0L)
                                if ((accountFilter > 0)) {
                                    try {
                                        store!!.account(accountFilter)
                                    } catch (e: Exception) {
                                        accountFilter = 0L
                                    }
                                }
                                if ((searchMenu!![0] != null)) {
                                    (searchMenu!![0])!!.dismiss()
                                }
                                render()
                            } catch (e: Exception) {
                                toast(e!!.message)
                            }
                        }))
                        f!!.addView(button("מחיקת החיפוש", false, compat.j.Runnable l126@{
                            try {
                                var updated: org.json.JSONArray? = org.json.JSONArray()
                                run {
                                    var k: Int = 0
                                    while (k < (all!!.length())) {
                                        if ((k != index)) {
                                            updated!!.put(all!!.get(k))
                                        }
                                        k++
                                    }
                                }
                                var next: org.json.JSONObject? = (Tools.read(this))!!.put("searches", updated)
                                edit("מחיקת חיפוש", Store.Change l127@{ Tools.write(this, next, true) })
                                if ((searchMenu!![0] != null)) {
                                    (searchMenu!![0])!!.dismiss()
                                }
                                render()
                            } catch (e: Exception) {
                                toast(e!!.message)
                            }
                        }))
                    } finally {
                        n++
                    }
                }
            }
        }
        var scroll: android.widget.ScrollView? = android.widget.ScrollView(this)
        scroll!!.addView(f)
        searchMenu!![0] = (trackDialog(((((android.app.AlertDialog.Builder(this)).setTitle("חיפושים שמורים"))!!.setView(scroll))!!.setPositiveButton("סגירה", null))!!.create()))!!
        (searchMenu!![0])!!.show()
    }
