    private fun ruleDialog(existing: Store.Rule?) {
        var ac: MutableList<Store.Account>? = ArrayList<Store.Account>()
        var names: MutableList<String>? = ArrayList<String>()
        for (a in paymentAccounts()!!) {
            if ((!((a!!.type)!!.equals("cash")) && !((a!!.type)!!.equals("check")))) {
                ac!!.add(a!!)
                names!!.add((a!!.name)!!)
