            toast("לפני הוראת קבע יש להוסיף חשבון בנק או כרטיס")
            tab = 4
            render()
            return
        }
        var f: android.widget.LinearLayout? = form()
        var name: android.widget.AutoCompleteTextView? = historyField(f, "שם הוראת הקבע / בית העסק", (if (existing == null) "" else existing!!.name), store!!.suggestions(false))
        var fx: MainActivity.CurrencyEntry? = CurrencyEntry(f, ruleCurrency(existing))
