        var account: android.widget.Spinner? = spinner(f, "חשבון בנק או כרטיס לחיוב", names)
        if ((existing != null)) {
            run {
                var n: Int = 0
                while (n < (ac!!.size)) {
                    if ((((ac!!.get(n))!!.id) == (existing!!.account))) {
                        account!!.setSelection(n)
