                    n++
                }
            }
        }
        var feePreview: compat.j.Runnable? = compat.j.Runnable l138@{ fx!!.selectAccount(ac!!.get(account!!.selectedItemPosition), null, true) }
        run { account!!.onItemSelectedListener = selection(feePreview) }
        feePreview!!.run()
        hint(f, "הסכום והשער נשמרים בהוראה. לחיובים חדשים מתווספת עמלת הכרטיס שהוגדרה בעת יצירת החיוב. אפשר לעדכן שער בהוראה או בחיוב בודד.")
        var start: android.widget.TextView? = dateField(f, "מועד החיוב הראשון", (if (existing == null) compat.time.LocalDate.now()!!.toString() else existing!!.start))
        var end: android.widget.EditText? = field(f, "תאריך סיום · YYYY-MM-DD · לבחירה", (if (existing == null) "" else existing!!.end), false)
        var frequency: android.widget.Spinner? = spinner(f, "תדירות החיוב", compat.j.Arrays.asList("כל חודש", "כל שלושה חודשים", "כל שנה"))
        frequency!!.setSelection((if (existing == null) 0 else (if ((existing!!.interval) == 12) 2 else (if ((existing!!.interval) == 3) 1 else 0))))
        var reminder: android.widget.EditText? = field(f, "תזכורת לפני חידוש · ימים", (if (existing == null) "7" else "" + existing!!.reminderDays), true)
        var renewal: android.widget.EditText? = field(f, "מועד חידוש מיוחד · YYYY-MM-DD · לבחירה", (if (existing == null) "" else existing!!.renewal), false)
        hint(f, "ללא מועד מיוחד, התזכורת לפי החיוב הבא. מועד מיוחד נשאר עד שתעדכן אותו. בחודש קצר החיוב עובר ליום האחרון בחודש.")
        if ((existing != null)) {
