        dialog((if (existing == null) "הוראת קבע חדשה" else "עריכת הוראת קבע"), f, MainActivity.Save l139@{
            var r: Store.Rule? = Store.Rule()
            r!!.id = (if (existing == null) 0L else existing!!.id)
            r!!.name = required(name, "שם")
            fx!!.selectAccount(ac!!.get(account!!.selectedItemPosition), null, true)
            var converted: Store.Tx? = Store.Tx()
            fx!!.apply(converted)
            r!!.amount = converted!!.amount
            r!!.originalAmount = converted!!.originalAmount
            r!!.currency = converted!!.currency
            r!!.fxRate = converted!!.fxRate
            r!!.fxFee = converted!!.fxFee
            r!!.fxDate = converted!!.fxDate
            r!!.fxSource = converted!!.fxSource
