    private fun ruleCurrency(rule: Store.Rule?): Store.Tx? {
        if ((rule == null)) {
            return null
        }
        var entry: Store.Tx? = Store.Tx()
        entry!!.amount = rule!!.amount
        entry!!.originalAmount = rule!!.originalAmount
        entry!!.currency = rule!!.currency
        entry!!.fxRate = rule!!.fxRate
        entry!!.fxFee = rule!!.fxFee
        entry!!.fxDate = rule!!.fxDate
        entry!!.fxSource = rule!!.fxSource
        return entry
    }
