    private fun forecastTotals(period: compat.time.YearMonth?): MainActivity.ForecastTotals? {
        store!!.ensureReportPeriod(period)
        var totals: MainActivity.ForecastTotals? = MainActivity.ForecastTotals()
        for (charge in (store!!.periodCharges(period))!!) {
            if (("income".equals(charge!!.kind))) {
                totals!!.income = totals!!.income - (charge!!.amount)
            } else {
                totals!!.charges = totals!!.charges + (charge!!.amount)
            }
        }
        return totals
    }
