    protected override fun onActivityResult(request: Int, result: Int, data: android.content.Intent?) {
        super.onActivityResult(request, result, data)
        if ((appLock!!.result(request, result))) {
            return
        }
        if ((request == 201)) {
            driveAuthorizationResult(result, data)
            return
        }
        var saving: Boolean = request == 101 || request == 103 || request == 105
        var restoring: Boolean = request == 102 || request == 104
        if ((!saving && !restoring)) {
            return
        }
        var draft: compat.io.File? = compat.io.File(this.cacheDir!!, "export-draft")
        if ((result != RESULT_OK || data == null || data!!.data == null)) {
            if ((saving)) {
                draft!!.delete()
                pendingExport = ""
            }
            return
        }
        if ((backupBusy())) {
            toast("העברת גיבוי מתבצעת כעת")
            return
        }
        backupTransfer = BackupTransfer(request, data!!.data)
        backupTransfer!!.attach(BackupTransfer.Completion { a0 -> this.completeTransfer(a0) })
        backupTransfer!!.start(this)
        if ((tab == 6)) {
            render()
        }
        toast((if (saving) "שומר קובץ גיבוי\u2026" else "קורא קובץ גיבוי\u2026"))
    }
    private fun completeTransfer(transfer: BackupTransfer?) {
        backupTransfer = null
        var saving: Boolean = (transfer!!.request) == 101 || (transfer!!.request) == 103 || (transfer!!.request) == 105
        var draft: compat.io.File? = compat.io.File(this.cacheDir!!, "export-draft")
        var uri: android.net.Uri? = transfer!!.uri
        if ((transfer!!.error != null)) {
            if ((saving)) {
                draft!!.delete()
                pendingExport = ""
            } else {
                clearRestore()
            }
            if ((tab == 6)) {
                render()
            }
            toast((if (saving) "שמירת הקובץ נכשלה. בדוק הרשאות, מקום פנוי וחיבור לאינטרנט." else "לא ניתן לקרוא את הגיבוי. בדוק את הקובץ ואת החיבור ל־Drive. הנתונים לא השתנו."))
            return
        }
        if ((saving)) {
            draft!!.delete()
            pendingExport = ""
            if (((transfer!!.request) != 101)) {
                var history: android.content.SharedPreferences.Editor? = (((getSharedPreferences("backup-history", MODE_PRIVATE))!!.edit())!!.putLong("savedAt", compat.util.System.currentTimeMillis()))!!.putString("destination", (if (BackupFiles.isDrive(uri)) "Google Drive" else "מיקום שנבחר"))
                if ((BackupFiles.isDrive(uri))) {
                    history!!.putString("driveUri", uri!!.toString())
                }
                history!!.apply()
            }
            if ((tab == 6)) {
                render()
            }
            toast((if (BackupFiles.isDrive(uri)) "קובץ הגיבוי נשמר דרך Drive. יש לוודא שההעלאה לענן הושלמה ב־Drive." else "הקובץ נשמר"))
        } else {
            if ((BackupFiles.isDrive(uri))) {
                (((getSharedPreferences("backup-history", MODE_PRIVATE))!!.edit())!!.putString("driveUri", uri!!.toString()))!!.apply()
            }
            pendingRestore = true
            if ((tab == 6)) {
                render()
            } else {
                showRestorePreview()
            }
        }
    }
